import { useState, useRef, useEffect, useCallback, useLayoutEffect } from 'react'
import { ChevronDown, Brain } from 'lucide-react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { cn } from '@/lib/utils'
import { CodeBlock } from '@/components/chat/CodeBlock'

interface ReasoningBlockProps {
  text: string
  isStreaming: boolean
}

/** 提取最后一行（streaming 时显示最新内容）。 */
function latestLine(text: string): string {
  const visible = text.trimEnd()
  const newline = visible.lastIndexOf('\n')
  return newline === -1 ? visible : visible.slice(newline + 1)
}

/** 提取第一行（完成后显示摘要）。 */
function firstLine(text: string): string {
  const newline = text.indexOf('\n')
  return newline === -1 ? text : text.slice(0, newline)
}

/**
 * rAF 节流视觉更新 hook（参照 deepseek-harness useThrottledVisualUpdate）。
 * 合并高频 DOM 写操作，每 intervalFrames 帧执行一次。
 */
function useThrottledVisualUpdate(
  update: () => void,
  intervalFrames = 3,
): () => void {
  const updateRef = useRef(update)
  updateRef.current = update
  const pendingFrameRef = useRef<number | null>(null)

  useLayoutEffect(() => () => {
    if (pendingFrameRef.current === null) return
    cancelAnimationFrame(pendingFrameRef.current)
    pendingFrameRef.current = null
  }, [])

  return useCallback(() => {
    if (pendingFrameRef.current !== null) return
    let remainingFrames = intervalFrames
    const advance = (): void => {
      remainingFrames -= 1
      if (remainingFrames > 0) {
        pendingFrameRef.current = requestAnimationFrame(advance)
        return
      }
      pendingFrameRef.current = null
      updateRef.current()
    }
    pendingFrameRef.current = requestAnimationFrame(advance)
  }, [intervalFrames])
}

/**
 * 思考过程展示块（参照 deepseek-harness ReasoningRow）
 * - 默认折叠，streaming 时显示 latestLine（最新一行），完成后显示 firstLine（摘要）
 * - streaming 时标题行有扫光动画 + 脉冲效果
 * - 点击展开查看完整思考内容（Markdown 渲染）
 */
export function ReasoningBlock({ text, isStreaming }: ReasoningBlockProps) {
  const [open, setOpen] = useState(false)
  // 摘要文本引用：streaming 时显示最新行，完成后显示首行
  const summary = isStreaming ? latestLine(text) : firstLine(text)
  // 摘要文本 DOM 引用（用于水平滚动）
  const summaryRef = useRef<HTMLSpanElement>(null)

  // rAF 节流的滚动更新：streaming 时滚到右侧（最新内容），完成后滚到左侧
  const scheduleSummaryScroll = useThrottledVisualUpdate(() => {
    const el = summaryRef.current
    if (el === null) return
    el.scrollLeft = isStreaming ? el.scrollWidth - el.clientWidth : 0
  })

  // summary 变化时触发滚动更新
  useEffect(() => {
    scheduleSummaryScroll()
  }, [isStreaming, scheduleSummaryScroll, summary])

  return (
    <div className={cn('w-full rounded-lg border border-border/40 bg-muted/30', isStreaming && 'overflow-hidden')}>
      {/* 标题行：状态 + 摘要预览 + 展开箭头 */}
      <div className="relative">
        <button
          type="button"
          onClick={() => setOpen(!open)}
          className="group flex w-full cursor-pointer items-center gap-2 px-3 py-2 text-sm text-muted-foreground transition-colors hover:text-foreground hover:bg-muted/50"
        >
          <Brain className="h-4 w-4 shrink-0" />
          <span className={cn(isStreaming && 'animate-pulse', 'shrink-0')}>
            {isStreaming ? '思考中...' : '思考结束'}
          </span>
          {/* 分隔点 */}
          {text && (
            <span className="w-0.5 h-0.5 rounded-full bg-muted-foreground/40 shrink-0" aria-hidden />
          )}
          {/* 摘要预览：单行溢出，streaming 时自动滚到右侧显示最新内容 */}
          {text && (
            <span
              ref={summaryRef}
              className={cn(
                'flex-1 min-w-0 overflow-hidden whitespace-nowrap text-xs text-muted-foreground/60 text-left',
                isStreaming ? 'text-clip' : 'text-ellipsis',
              )}
            >
              {summary}
            </span>
          )}
          <ChevronDown
            className={cn(
              'ml-auto h-3.5 w-3.5 shrink-0 text-muted-foreground/70 transition-transform duration-150',
              open && 'rotate-180',
            )}
          />
        </button>
        {/* streaming 时扫光动画（从左到右的渐变覆盖层） */}
        {isStreaming && (
          <div
            className="pointer-events-none absolute inset-y-0 left-0 w-[300px]"
            style={{
              background: 'linear-gradient(90deg, transparent 0%, rgba(128,128,128,0.08) 55%, transparent 100%)',
              animation: 'reasoning-sweep 2.6s ease-out infinite',
            }}
          />
        )}
      </div>
      {/* 展开后：完整思考内容（Markdown 渲染） */}
      {open && (
        <div className="border-t border-border/40 px-3 py-2">
          <div className="prose prose-sm max-w-none text-muted-foreground">
            <ReactMarkdown
              remarkPlugins={[remarkGfm]}
              components={{
                code({ node: _node, className, children, ...props }) {
                  const match = /language-(\w+)/.exec(className || '')
                  const isInline = !match
                  if (isInline) {
                    return <code className="rounded bg-muted px-1.5 py-0.5 text-xs font-mono" {...props}>{children}</code>
                  }
                  return <CodeBlock code={String(children).replace(/\n$/, '')} language={match?.[1] || 'text'} />
                },
              }}
            >
              {text}
            </ReactMarkdown>
          </div>
        </div>
      )}
      {/* 扫光动画 keyframes */}
      <style>{`
        @keyframes reasoning-sweep {
          0% { left: -300px; }
          90%, 100% { left: 100%; }
        }
        @media (prefers-reduced-motion: reduce) {
          [style*="reasoning-sweep"] { animation: none !important; }
        }
      `}</style>
    </div>
  )
}
